{"command": "python3 <<'PY'
import subprocess, time, os
def caplines():
    r=subprocess.run(["tmux","capture-pane","-t","test","-p"], capture_output=True, text=True)
    return r.stdout.splitlines()
def sendkeys(*keys, delay=0.6):
    subprocess.run(["tmux","send-keys","-t","test"]+list(keys))
    time.sleep(delay)
def sendcmd(cmd, delay=1.0):
    subprocess.run(["tmux","send-keys","-t","test",cmd,"Enter"])
    time.sleep(delay)

for f in ["/tmp/pipe_cap.txt","/tmp/pipe_out.txt"]:
    try: os.remove(f)
    except: pass
sendcmd("./executable --no-isolation > /tmp/pipe_cap.txt")
# type: echo hello | tr a-z A-Z | cat
for c in "echo hello | tr a-z A-Z":
    sendkeys(c, delay=0.15)
time.sleep(0.8)
print("PIPE test:")
for l in caplines()[:15]:
    print(repr(l[:150]))
sendkeys("Escape")
time.sleep(0.7)
print("PIPE_CAP:",repr(open("/tmp/pipe_cap.txt","rb").read()))

# Test cursor position impact? F7 caching? Try F7 on |
PY
"}

